/**
 * Unified Language Handler for JobsInIraq - Minified
 * @version 3.1.0 - With Complete Navigation RTL Reordering Fix
 */
(function(){'use strict';const CONFIG={supportedLangs:['en','ar','ku'],rtlLangs:['ar','ku'],storageKey:'siteLanguage',defaultLang:'en',debug:false};function log(type,...args){if(!CONFIG.debug)return;const prefix='[i18n]';switch(type){case'info':console.log(prefix,...args);break;case'warn':console.warn(prefix,...args);break;case'error':console.error(prefix,...args);break;default:console.log(prefix,...args)}}function isRTL(lang){return CONFIG.rtlLangs.includes(lang)}function isValidLang(lang){return CONFIG.supportedLangs.includes(lang)}class UnifiedLanguageManager{constructor(){this.currentLang=this.getSavedLanguage();this.initialized=false;this.originalVisibleItems=[];this.originalHiddenItems=[];this.navObserver=null;this.isReordering=false;this.resizeTimeout=null;this.init()}getSavedLanguage(){try{const saved=localStorage.getItem(CONFIG.storageKey);if(saved&&isValidLang(saved)){return saved}}catch(e){log('warn','localStorage unavailable:',e.message)}return CONFIG.defaultLang}init(){log('info','Initializing language manager v3.1.0...');this.applyLanguage(this.currentLang);if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>{this.onDOMReady()})}else{this.onDOMReady()}this.initialized=true}onDOMReady(){this.cacheOriginalNavOrder();this.initializePicker();this.setupEventListeners();this.updateNavigationText(this.currentLang);if(isRTL(this.currentLang)){this.reverseNavigationForRTL()}this.setupNavObserver()}cacheOriginalNavOrder(){const visibleLinks=document.querySelector('.greedy-nav .visible-links');const hiddenLinks=document.querySelector('.greedy-nav .hidden-links');if(!visibleLinks)return;const visibleItems=visibleLinks.querySelectorAll(':scope > li');const hiddenItems=hiddenLinks?hiddenLinks.querySelectorAll(':scope > li'):[];this.originalVisibleItems=Array.from(visibleItems).map(li=>({key:this.getNavItemKey(li),html:li.outerHTML}));this.originalHiddenItems=Array.from(hiddenItems).map(li=>({key:this.getNavItemKey(li),html:li.outerHTML}))}getNavItemKey(li){const link=li.querySelector('a');if(link){return link.getAttribute('data-i18n-key')||link.getAttribute('href')||link.textContent.trim()}return li.textContent.trim()}reverseNavigationForRTL(){const visibleLinks=document.querySelector('.greedy-nav .visible-links');const hiddenLinks=document.querySelector('.greedy-nav .hidden-links');if(!visibleLinks)return;this.isReordering=true;this.reverseContainerItems(visibleLinks);if(hiddenLinks){this.reverseContainerItems(hiddenLinks)}visibleLinks.setAttribute('data-rtl-reversed','true');if(hiddenLinks){hiddenLinks.setAttribute('data-rtl-reversed','true')}setTimeout(()=>{this.isReordering=false},100)}reverseContainerItems(container){const items=Array.from(container.querySelectorAll(':scope > li'));if(items.length<=1)return;items.forEach(item=>item.remove());items.reverse().forEach(item=>{container.appendChild(item)})}restoreOriginalNavOrder(){const visibleLinks=document.querySelector('.greedy-nav .visible-links');const hiddenLinks=document.querySelector('.greedy-nav .hidden-links');if(!visibleLinks)return;this.isReordering=true;if(this.originalVisibleItems.length===0){if(visibleLinks.getAttribute('data-rtl-reversed')==='true'){this.reverseContainerItems(visibleLinks);visibleLinks.removeAttribute('data-rtl-reversed')}if(hiddenLinks&&hiddenLinks.getAttribute('data-rtl-reversed')==='true'){this.reverseContainerItems(hiddenLinks);hiddenLinks.removeAttribute('data-rtl-reversed')}setTimeout(()=>{this.isReordering=false},100);return}const allCurrentItems=new Map();visibleLinks.querySelectorAll(':scope > li').forEach(li=>{const key=this.getNavItemKey(li);allCurrentItems.set(key,li)});if(hiddenLinks){hiddenLinks.querySelectorAll(':scope > li').forEach(li=>{const key=this.getNavItemKey(li);allCurrentItems.set(key,li)})}visibleLinks.innerHTML='';if(hiddenLinks){hiddenLinks.innerHTML=''}this.originalVisibleItems.forEach(cached=>{const currentLi=allCurrentItems.get(cached.key);if(currentLi){visibleLinks.appendChild(currentLi);allCurrentItems.delete(cached.key)}});if(hiddenLinks){this.originalHiddenItems.forEach(cached=>{const currentLi=allCurrentItems.get(cached.key);if(currentLi){hiddenLinks.appendChild(currentLi);allCurrentItems.delete(cached.key)}});allCurrentItems.forEach(li=>{hiddenLinks.appendChild(li)})}visibleLinks.removeAttribute('data-rtl-reversed');if(hiddenLinks){hiddenLinks.removeAttribute('data-rtl-reversed')}setTimeout(()=>{this.isReordering=false},100)}updateNavigationOrder(rtl){if(rtl){this.reverseNavigationForRTL()}else{this.restoreOriginalNavOrder()}}setupNavObserver(){const visibleLinks=document.querySelector('.greedy-nav .visible-links');const hiddenLinks=document.querySelector('.greedy-nav .hidden-links');if(!visibleLinks)return;this.disconnectNavObserver();this.navObserver=new MutationObserver((mutations)=>{if(this.isReordering)return;const hasChildChanges=mutations.some(m=>m.type==='childList'&&(m.addedNodes.length>0||m.removedNodes.length>0));if(hasChildChanges&&isRTL(this.currentLang)){setTimeout(()=>{visibleLinks.removeAttribute('data-rtl-reversed');if(hiddenLinks){hiddenLinks.removeAttribute('data-rtl-reversed')}this.reverseNavigationForRTL()},50)}});const observerConfig={childList:true,subtree:false};this.navObserver.observe(visibleLinks,observerConfig);if(hiddenLinks){this.navObserver.observe(hiddenLinks,observerConfig)}}disconnectNavObserver(){if(this.navObserver){this.navObserver.disconnect();this.navObserver=null}}applyLanguage(lang){if(!isValidLang(lang)){lang=CONFIG.defaultLang}const rtl=isRTL(lang);const previousLang=this.currentLang;const wasRTL=isRTL(previousLang);document.documentElement.setAttribute('lang',lang);document.documentElement.setAttribute('dir',rtl?'rtl':'ltr');document.documentElement.setAttribute('data-locale',lang);if(document.body){document.body.setAttribute('data-locale',lang);document.body.setAttribute('data-rtl',rtl?'true':'false');document.body.classList.toggle('rtl',rtl);document.body.classList.toggle('ltr',!rtl)}this.updateNavigationText(lang);if(this.initialized&&rtl!==wasRTL){this.updateNavigationOrder(rtl)}try{localStorage.setItem(CONFIG.storageKey,lang)}catch(e){}this.currentLang=lang;this.broadcastChange(lang,rtl)}updateNavigationText(lang){const translations=window.SITE_TRANSLATIONS;if(!translations)return;const langTranslations=translations[lang];if(!langTranslations)return;document.querySelectorAll('[data-i18n-key]').forEach(element=>{const key=element.getAttribute('data-i18n-key');if(key&&langTranslations[key])element.textContent=langTranslations[key]});document.querySelectorAll('[data-i18n]').forEach(element=>{const key=element.getAttribute('data-i18n');const value=this.getNestedTranslation(langTranslations,key);if(value){if(element.tagName==='INPUT'||element.tagName==='TEXTAREA'){element.placeholder=value}else{element.textContent=value}}})}getNestedTranslation(obj,key){if(!key||!obj)return null;const keys=key.split('.');let value=obj;for(const k of keys){if(value&&typeof value==='object'&&k in value){value=value[k]}else{return null}}return typeof value==='string'?value:null}initializePicker(){const picker=document.getElementById('globalLangPicker');if(!picker)return;picker.value=this.currentLang;picker.addEventListener('change',(e)=>{this.applyLanguage(e.target.value)})}setupEventListeners(){window.addEventListener('languageChanged',(e)=>{if(e.detail&&e.detail.language&&e.detail.language!==this.currentLang){this.applyLanguage(e.detail.language)}});window.addEventListener('popstate',()=>{const saved=this.getSavedLanguage();if(saved!==this.currentLang)this.applyLanguage(saved)});window.addEventListener('resize',()=>{if(this.resizeTimeout){clearTimeout(this.resizeTimeout)}this.resizeTimeout=setTimeout(()=>{if(isRTL(this.currentLang)){const visibleLinks=document.querySelector('.greedy-nav .visible-links');const hiddenLinks=document.querySelector('.greedy-nav .hidden-links');if(visibleLinks)visibleLinks.removeAttribute('data-rtl-reversed');if(hiddenLinks)hiddenLinks.removeAttribute('data-rtl-reversed');this.reverseNavigationForRTL()}},250)});window.addEventListener('beforeunload',()=>{this.destroy()})}broadcastChange(lang,rtl){window.dispatchEvent(new CustomEvent('languageChanged',{detail:{language:lang,isRTL:rtl,timestamp:Date.now()}}))}destroy(){if(this.resizeTimeout){clearTimeout(this.resizeTimeout);this.resizeTimeout=null}this.disconnectNavObserver();this.isReordering=false}getLanguage(){return this.currentLang}setLanguage(lang){this.applyLanguage(lang)}isRTL(){return isRTL(this.currentLang)}t(key){const translations=window.SITE_TRANSLATIONS;if(!translations||!translations[this.currentLang])return key;return this.getNestedTranslation(translations[this.currentLang],key)||key}getSupportedLanguages(){return[...CONFIG.supportedLangs]}refreshNavigationOrder(){this.updateNavigationOrder(isRTL(this.currentLang))}}window.languageManager=new UnifiedLanguageManager();window.i18n=window.languageManager})();